// Return a debounced version of fn.
// Calling it repeatedly should reset the timer; fn runs once, after the pause.
function debounce(fn, delay) {
  // your code here
}

solutionCode:
function debounce(fn, delay) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

