// Return a throttled version of fn that runs at most once per `limit` ms.
function throttle(fn, limit) {
  // your code here
}

solutionCode:
function throttle(fn, limit) {
  let last = 0;
  return function (...args) {
    const now = Date.now();
    if (now - last >= limit) {
      last = now;
      fn.apply(this, args);
    }
  };
}

