// Return a curried version of fn (use fn.length for arity).
function curry(fn) {
  // your code here
}

solutionCode:
function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) return fn.apply(this, args);
    return (...rest) => curried.apply(this, args.concat(rest));
  };
}

